"""Generate sql/00_seed_model.sql (MODEL.ZONES) from BUSINESS_MODEL.md. The lens is compiled into prompts (prompts/compile.py)."""
import re, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
q = lambda s: "'" + s.replace("'", "''") + "'"

rows, zone = [], None
for line in (root / "BUSINESS_MODEL.md").read_text().splitlines():
    m = re.match(r"\|\s*(\*\*(\w+)\*\*)?\s*\|\s*`(\w+)`\s*\|\s*(.+?)\s*\|\s*(.+?)\s*\|$", line)
    if m:
        zone = m.group(2) or zone
        rows.append((zone, m.group(3), m.group(4), m.group(5)))


out = [
    "-- Generated by sql/gen_seed.py from BUSINESS_MODEL.md. Do not edit by hand.",
    "create schema if not exists RECPLACE.MODEL;",
    "create or replace table RECPLACE.MODEL.ZONES (zone string, subzone string, question string, sources string);",
    "insert into RECPLACE.MODEL.ZONES values\n" + ",\n".join(f"  ({q(a)}, {q(b)}, {q(c)}, {q(d)})" for a, b, c, d in rows) + ";",
]
(root / "sql" / "00_seed_model.sql").write_text("\n\n".join(out) + "\n")
print(f"zones={len(rows)}")
